import { DIRECT_SHORTCUTS, QUICK_ACTIONS } from '../keyboard-registry';
/**
 * Help Centre content: the ONE source for the in-app Help tab and docs/user-guide/POS_USER_MANUAL.md
 * (generated by `npm run manual`; a test fails if the manual is out of date).
 *
 * Rules for writers:
 * - Teach only what the app does today. Do not describe features that are not built.
 * - Plain, respectful English for someone standing at the counter. Short steps, one action each.
 * - Button and field names exactly as on screen (English UI). Example names and numbers are made up.
 * - English only for now (owner decision 2026-11-07); the Arabic UI shows a notice.
 */
export type HelpSectionId =
  | 'start' | 'selling' | 'payments' | 'customers' | 'suppliers' | 'stock' | 'returns' | 'expenses' | 'reports' | 'shifts' | 'backup' | 'scenarios';

export interface HelpArticle {
  id: string;
  section: HelpSectionId;
  title: string;
  /** Extra words people may search for. */
  keywords: string[];
  /** What this does, in one or two sentences. */
  what: string;
  /** Where to find it in the app. */
  where?: string;
  steps: string[];
  /** What you should see when it worked. */
  expect: string;
  problems: { problem: string; fix: string }[];
  /** When to ask a supervisor or the owner. */
  supervisor?: string;
  /** Keyboard keys used, shown as key caps. */
  keys?: string[];
}

export const HELP_SECTIONS: { id: HelpSectionId; title: string }[] = [
  { id: 'start', title: 'Getting started' },
  { id: 'selling', title: 'Selling' },
  { id: 'payments', title: 'Taking payments' },
  { id: 'customers', title: 'Customers and credit' },
  { id: 'suppliers', title: 'Suppliers and purchasing' },
  { id: 'stock', title: 'Stock and products' },
  { id: 'returns', title: 'Returns and refunds' },
  { id: 'expenses', title: 'Expenses and accounts' },
  { id: 'reports', title: 'Reports and the owner overview' },
  { id: 'shifts', title: 'Shifts and daily work' },
  { id: 'backup', title: 'Backup and recovery' },
  { id: 'scenarios', title: 'Real situations, step by step' },
];

